import json

# Load the JSON files
with open('/app/resources/treasury_bulletin_1962_04.json', 'r') as f:
    data_1962 = json.load(f)

# Look for table data about Treasury Notes
# Check if there's a tables key or similar
def find_notes_data(data, year):
    if isinstance(data, dict):
        for key, value in data.items():
            if 'note' in key.lower() or 'table' in key.lower():
                print(f"{year} - Key: {key}")
                if isinstance(value, list):
                    print(f"  List length: {len(value)}")
                    if len(value) > 0:
                        print(f"  First item: {str(value[0])[:500]}")
            find_notes_data(value, year)
    elif isinstance(data, list):
        for item in data[:3]:  # Just check first few
            find_notes_data(item, year)

find_notes_data(data_1962, "1962")
